// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Private_Bank} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank(address(this));
    }

    function _testDepositIncreasesBalance(address user, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > c.MinDeposit());
        vm.assume(user != address(0));
        vm.assume(c.balances(user) + amount >= c.balances(user));
        user = address(this);
        uint256 pre;
        try c.balances(user) returns (uint256 __r) { pre = __r; } catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 post;
        try c.balances(user) returns (uint256 __r) { post = __r; } catch { return; }
        assertTrue(post >= pre + amount);
    }

    function testFuzz_testDepositIncreasesBalance(address user, uint256 amount) public {
        _testDepositIncreasesBalance(user, amount);
    }

    receive() external payable {}
}
